mapper.select:
    	select sum(count) from(
		 select count(*) count from MST_COUNTER_ACCT T1 ,STL_CAPACCT_INFO T2 
		 	where T1.ACCT_NO=T2.ACCT_NO 
		 		and T1.CCY=T2.CCY 
		 		and T2.ACCT_NO = #{acctNo,jdbcType=VARCHAR} 
		 		and T2.CCY = #{ccy,jdbcType=VARCHAR}
		 union all select count(*) count from STL_FIN_PRODUCT_ACCT T3 ,STL_CAPACCT_INFO T4 
		 	where T3.ACCT_NO=T4.ACCT_NO 
		 		and T3.CCY=T4.CCY 
		 		and T4.ACCT_NO = #{acctNo,jdbcType=VARCHAR} 
		 		and T4.CCY = #{ccy,jdbcType=VARCHAR}
		 union all select count(*) count from PTL_CAPACCT_INFO T5 ,STL_CAPACCT_INFO T6 
		 	where T5.ACCT_NO=T6.ACCT_NO 
		 		and T5.CCY=T6.CCY 
		 		and T6.ACCT_NO = #{acctNo,jdbcType=VARCHAR}
		 		and T6.CCY = #{ccy,jdbcType=VARCHAR}
		)
